.icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--control-radius);
  background: transparent;
  /* Full-strength ink. `quiet` is the one that sits in secondary ink, and that
   * difference is now the only thing separating the two at rest — until this,
   * `ghost` and `quiet` drew the identical button and diverged only once the
   * pointer arrived, which is two names for one picture. */
  color: var(--foreground);
  transition: opacity var(--duration-fast), background var(--duration-fast), color var(--duration-fast);
}
/* Icon buttons are square buttons — heights match the regular control heights. */
.icon-button[data-size="sm"] { width: var(--control-height-sm); height: var(--control-height-sm); }   /* 32px */
.icon-button[data-size="md"] { width: var(--control-height); height: var(--control-height); }          /* 40px */
.icon-button[data-size="lg"] { width: var(--control-height-lg); height: var(--control-height-lg); }    /* 52px */

.icon-button:hover,
.icon-button[data-open] {
  background: var(--accent-soft);
  color: var(--accent-foreground);
}
.icon-button:disabled {
  opacity: var(--disabled-opacity);
  cursor: not-allowed;
  pointer-events: none;
}
.icon-button[data-loading] {
  opacity: 1;
  cursor: progress;
  pointer-events: none;
}

/* Filled — the icon button that carries a surface of its own: a header back, a
 * row of actions under a portrait. Which fill that is depends on what it is
 * sitting on, and it asks rather than assumes: --surface-contrast is white on
 * the grey page and grey on a white card, and the hover step always moves one
 * stop FURTHER from the surface. Painting `--card` on hover unconditionally is
 * what made it disappear on a card (owner, 2026-08-22). */
.icon-button[data-variant="filled"] {
  background: var(--surface-contrast);
  color: var(--foreground);
}
/* Pressed: one stop past hover, the same third step the button family gained. */
.icon-button:active { background: var(--accent); }
.icon-button[data-variant="filled"]:active { background: var(--surface-contrast-active); }
/* The fill moves, the ink stays. It used to recolour the glyph to the brand on
 * hover, which no other control in the family does — a secondary button does not
 * turn its label blue — so three icon buttons in a row answered the pointer two
 * different ways (owner, 2026-08-23). Hover means one thing here: one stop
 * further from the surface. */
.icon-button[data-variant="filled"]:hover,
.icon-button[data-variant="filled"][data-open] {
  background: var(--surface-contrast-hover);
}

/* Quiet — never grows a background, and sits in secondary ink so it reads as
 * quieter than `ghost` BEFORE anyone touches it. Inline toolbar icons (chat
 * search/filter/close, 3-dot menus) that must not add furniture to a dense row.
 * The whole variant is one sentence: it answers with ink, never with fill. */
.icon-button[data-variant="quiet"] { color: var(--muted-foreground); }
.icon-button[data-variant="quiet"]:hover,
.icon-button[data-variant="quiet"][data-open] { background: transparent; color: var(--foreground); }
.icon-button[data-variant="quiet"]:active { background: transparent; color: var(--primary-accent); }

/* Filled tones — solid brand / danger fill (e.g. composer send / stop). */
.icon-button[data-variant="filled"][data-tone="primary"] { background: var(--primary); color: var(--primary-foreground); }
.icon-button[data-variant="filled"][data-tone="primary"]:hover,
.icon-button[data-variant="filled"][data-tone="primary"][data-open] { background: var(--primary-hover); color: var(--primary-foreground); }
.icon-button[data-variant="filled"][data-tone="destructive"] { background: var(--destructive); color: var(--destructive-foreground); }
.icon-button[data-variant="filled"][data-tone="destructive"]:hover { background: var(--destructive); color: var(--destructive-foreground); opacity: 0.9; }

/* Hidden by default; container with :hover (or button itself open) makes it visible.
 * The "show on parent hover" rule lives in the consumer (e.g. .card[data-interactive]:hover). */
.icon-button[data-reveal] { opacity: 0; }
.icon-button[data-reveal][data-open] { opacity: 1; }

import './IconButton.css'
import { type ButtonHTMLAttributes, type Ref } from 'react'
import { cn } from '../lib/cn'
import { Icon, type IconName } from '../Icon'
import { Spinner } from '../Spinner'

type Size = 'sm' | 'md' | 'lg'
type Variant = 'ghost' | 'filled' | 'quiet'
type Tone = 'primary' | 'destructive'

type Props = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children'> & {
  /** Forwarded to the underlying <button>. */
  ref?: Ref<HTMLButtonElement>
  /** The glyph, which is also the entire label a sighted reader gets. It has to
   *  survive being the only thing there: a picture that needs a caption is a
   *  `<Button>` with words. The announced name comes from `aria-label`, which is
   *  not optional on this component. */
  icon: IconName
  /** Square button matching control heights: sm 32 / md 40 / lg 52. Default 'sm'.
   *  NOTE: `Button` defaults to 'md', so a pair of them needs this stated — an
   *  unsized icon button beside an unsized button is 32 next to 40. Three apps
   *  shipped that before `controls-same-height` started asking. */
  size?: Size
  /** ghost = transparent (default, hover = accent fill). filled = solid fill.
   *  quiet = transparent, hover recolors only (no fill) — for inline toolbar icons. */
  variant?: Variant
  /** Fill colour for `filled` (e.g. send = primary, stop = destructive). */
  tone?: Tone
  /** Hidden by default; container's :hover or `data-open` makes it visible. */
  reveal?: boolean
  /** In-flight action: swaps the icon for a spinner and blocks clicks. The
   *  spinner reuses the button's aria-label as its accessible name. */
  loading?: boolean
}

/* THE GLYPH IS THE CONTENT, so it scales with the button: 32 holds 16, 40 holds
 * 20, 52 holds 24.
 *
 * This reverses the 2026-08-22 answer, and the reason that answer was reached
 * still stands as an observation: a 40px `Button` holds a 16px icon, so a 40px
 * icon button holding 20px looked like two different icons at one control
 * height. The conclusion was wrong. An icon BESIDE a label is an accessory and
 * takes the small size; an icon-only button has no label, so the glyph is the
 * whole thing being pointed at. Shrinking it to match the accessory left a
 * 16px mark floating in 40px of nothing, which the owner reported twice
 * (2026-08-23) as "why are the icons so small". The two cases are different
 * cases, and one rule for both was the error.
 *
 * The superseded reasoning, kept because it is the half that is still true:
 * --icon-sm is what this system puts in a control BESIDE TEXT. That rule is
 * untouched; it simply never applied here. */
const GLYPH = { sm: 'sm', md: 'md', lg: 'lg' } as const

/**
 * A button whose label is an icon, which is why it always takes an aria-label
 * and a Tooltip. `quiet` for inline toolbars, `filled` plus `tone` for send
 * and stop.
 *
 * Copy: the aria-label is the same verb a worded button would carry, and it
 * names the target when a screen repeats the control: "Delete invoice
 * INV-1041", not "Delete".
 */
export function IconButton({
  icon, size = 'sm', variant, tone, reveal, loading, disabled, className, type = 'button', ref, ...rest
}: Props) {
  const label = rest['aria-label']
  return (
    <button
      ref={ref}
      type={type}
      className={cn('icon-button', className)}
      data-size={size}
      data-variant={variant}
      data-tone={tone}
      data-reveal={reveal || undefined}
      data-loading={loading || undefined}
      disabled={disabled || loading || undefined}
      aria-busy={loading || undefined}
      {...rest}
    >
      {loading ? <Spinner size={GLYPH[size]} label={label ?? 'Loading'} /> : <Icon name={icon} size={GLYPH[size]} />}
    </button>
  )
}
